package com.example.dsatracker.repository;import com.example.dsatracker.model.Problem;import org.springframework.data.jpa.repository.JpaRepository;import org.springframework.stereotype.Repository;import java.util.Optional;@Repositorypublic interface ProblemRepository extends JpaRepository<Problem, Long> {    boolean existsByLeetcodeId(Integer leetcodeId);    Optional<Problem> findByLeetcodeId(Integer leetcodeId);}